<?php
session_start();if(!isset($_SESSION["user_id"])){header("Location: login.php");exit;}
require "db.php";require_once "role_helpers.php";require_once "access_helpers.php";require_once "comment_helpers.php";require_once "csrf_helpers.php";require_once "announcement_helpers.php";
$user_id=(int)$_SESSION["user_id"];$st=$conn->prepare("SELECT role,department FROM users WHERE id=? AND active=1");$st->bind_param("i",$user_id);$st->execute();$me=$st->get_result()->fetch_assoc();$st->close();if(!$me){header("Location: login.php");exit;}
$role=$me["role"];$department=$me["department"] ?? "";$module=trim($_GET["module"]??"");$id=(int)($_GET["id"]??0);
$allowed=["Project","Task","Event","Team","File","Report","Training","Time Off"];if(!in_array($module,$allowed,true)||!userCanAccessWorkItem($conn,$user_id,$role,$department,$module,$id)){http_response_code(403);exit("You do not have permission to view these comments.");}
$item=workItemInfo($conn,$module,$id);if(!$item){http_response_code(404);exit("Record not found.");}
$st=$conn->prepare("SELECT c.*,u.first_name,u.last_name FROM comments c INNER JOIN users u ON u.id=c.user_id WHERE c.module=? AND c.record_id=? AND c.deleted_at IS NULL ORDER BY c.created_at ASC,c.id ASC");$st->bind_param("si",$module,$id);$st->execute();$r=$st->get_result();$comments=[];while($row=$r->fetch_assoc())$comments[]=$row;$st->close();
function e($v){return htmlspecialchars((string)($v??""),ENT_QUOTES,"UTF-8");}
?>
